/**
 * @description: User Portal Layout - sidebar + topbar + main content
 * @author: Institute User Portal
 */
import React, { useState } from 'react';
import Header from './Header';
import Topbar from './Topbar';
import HomeworkModal from '../Homework/HomeworkModal';

const Layout = ({ children }) => {
  const [showHomeworkModal, setShowHomeworkModal] = useState(false);

  const openHomework = () => setShowHomeworkModal(true);
  const closeHomework = () => setShowHomeworkModal(false);

  return (
    <div className="user-portal-layout">
      <Header onOpenHomework={openHomework} />
      <div className="user-portal-main">
        <Topbar onOpenHomework={openHomework} />
        <main className="user-portal-content">{children}</main>
      </div>
      <HomeworkModal show={showHomeworkModal} onClose={closeHomework} />
    </div>
  );
};

export default Layout;
